//! 🏗️ IFC4 typed headers, EXPRESS values and explicit entity relationships.
use super::{IfcSnapshot,IfcHeader,IfcEntity,IfcComplexType,IfcValue};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,FloatColumn,insert_ieee754,read_binary64,ieee754_is_null,validate_ieee754_row,reconstruct_text},*}};
use std::collections::{BTreeMap,BTreeSet};
const REAL:&[FloatColumn]=&[FloatColumn::Binary64(3)];
fn ordinal(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|e|e.to_string())}
fn word(text:&str)->Result<u64,String>{if text.len()>20{return Err("IFC identity exceeds unsigned64".into());}let value=text.parse::<u64>().map_err(|e|e.to_string())?;if value.to_string()!=text{return Err("IFC identity must be canonical unsigned64 decimal text".into());}Ok(value)}
fn tick(control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<(),String>{*count=count.checked_add(1).ok_or("IFC traversal count overflow")?;if *count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;}Ok(())}
fn ordered<'a>(mut rows:Vec<&'a SqliteRow>,index:usize,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<&'a SqliteRow>,String>{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;rows.sort_by_key(|row|row.integer(index).unwrap_or(i64::MIN));for(i,row)in rows.iter().enumerate(){if row.integer(index)?!=ordinal(i)?{return Err("IFC relationship ordinals must be contiguous and unique".into());}tick(control,count)?;}Ok(rows)}
fn groups<'a>(db:&'a SqliteDatabase,table:&str,index:usize,order:usize,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{let mut result=BTreeMap::<i64,Vec<&SqliteRow>>::new();for row in &db.table(table)?.rows{result.entry(row.integer(index)?).or_default().push(row);tick(control,count)?;}for rows in result.values_mut(){*rows=ordered(std::mem::take(rows),order,control,count)?;}Ok(result)}
enum Owner{Header(&'static str,usize),Argument(Option<i64>,Option<i64>,usize),Aggregate(i64,usize),Typed(i64,usize)}
fn project_value(root:&IfcValue,owner:Owner,identities:&BTreeMap<u64,i64>,projection:&mut Projection<'_,'_>)->Result<(),String>{let mut pending=vec![(root,owner)];while let Some((value,owner))=pending.pop(){projection.checkpoint()?;let mut cells=[Cell::Null;8];let reference;cells[0]=Cell::Text(match value{IfcValue::Unset=>"unset",IfcValue::Derived=>"derived",IfcValue::Integer(_)=>"integer",IfcValue::Real(_)=>"real",IfcValue::String(_)=>"string",IfcValue::Enum(_)=>"enum",IfcValue::Reference(_)=>"reference",IfcValue::Aggregate(_)=>"aggregate",IfcValue::TypedValue{..}=>"typedValue"});match value{IfcValue::Integer(v)=>cells[1]=Cell::Integer(*v),IfcValue::Real(v)=>cells[2]=Cell::Real(*v),IfcValue::String(v)=>cells[3]=Cell::Text(v),IfcValue::Enum(v)=>cells[4]=Cell::Text(v),IfcValue::Reference(v)=>{reference=v.to_string();cells[5]=Cell::Text(&reference);cells[6]=Cell::Integer(*identities.get(v).ok_or("dangling IFC entity reference")?);},IfcValue::TypedValue{name,..}=>cells[7]=Cell::Text(name),_=>{}}let id=insert_ieee754(projection,"ifc_value",&cells,REAL)?;match owner{Owner::Header(table,index)=>{projection.insert(table,&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Integer(id)])?;},Owner::Argument(entity,complex,index)=>{projection.insert("ifc_argument",&[entity.map_or(Cell::Null,Cell::Integer),complex.map_or(Cell::Null,Cell::Integer),Cell::Integer(ordinal(index)?),Cell::Integer(id)])?;},Owner::Aggregate(parent,index)=>{projection.insert("ifc_aggregate_element",&[Cell::Integer(parent),Cell::Integer(ordinal(index)?),Cell::Integer(id)])?;},Owner::Typed(parent,index)=>{projection.insert("ifc_typed_argument",&[Cell::Integer(parent),Cell::Integer(ordinal(index)?),Cell::Integer(id)])?;}}match value{IfcValue::Aggregate(items)|IfcValue::TypedValue{items,..}=>{projection.check_rows(pending.len().checked_add(items.len()).ok_or("IFC pending count overflow")?)?;for(index,item)in items.iter().enumerate().rev(){pending.push((item,if matches!(value,IfcValue::Aggregate(_)){Owner::Aggregate(id,index)}else{Owner::Typed(id,index)}));if index%256==0{projection.checkpoint()?;}}},_=>{}}}Ok(())}
fn values(db:&SqliteDatabase,identities:&BTreeMap<i64,u64>,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<BTreeMap<i64,IfcValue>,String>{let mut records=BTreeMap::new();for row in &db.table("ifc_value")?.rows{records.insert(row.rowid,row);tick(control,count)?;}let mut aggregates=groups(db,"ifc_aggregate_element",1,2,control,count)?;let mut typed=groups(db,"ifc_typed_argument",1,2,control,count)?;for(table,kind)in [(&aggregates,"aggregate"),(&typed,"typedValue")]{for parent in table.keys(){if records.get(parent).ok_or("dangling IFC value parent")?.text(1)?!=kind{return Err("IFC value relationship has wrong parent kind".into());}tick(control,count)?;}}
    let mut visited=BTreeSet::new();let mut complete=BTreeMap::new();for(table,index)in [("ifc_file_description_argument",3),("ifc_file_name_argument",3),("ifc_file_schema_argument",3),("ifc_argument",4)]{for root in &db.table(table)?.rows{let mut pending=vec![(root.integer(index)?,false)];while let Some((id,exit))=pending.pop(){tick(control,count)?;let row=*records.get(&id).ok_or("dangling IFC value ownership edge")?;if !exit{if !visited.insert(id){return Err("cyclic or multiply owned IFC value".into());}pending.push((id,true));for map in [&aggregates,&typed]{if let Some(children)=map.get(&id){for child in children.iter().rev(){pending.push((child.integer(3)?,false));tick(control,count)?;}}}continue;}
        validate_ieee754_row(row,9,REAL)?;let kind=row.text(1)?;for index in 2..9{let active=matches!((kind,index),("integer",2)|("real",3)|("string",4)|("enum",5)|("reference",6)|("reference",7)|("typedValue",8));if !active&&row.values[index]!=SqliteValue::Null{return Err("unexpected IFC value variant field".into());}}if kind!="real"&&!ieee754_is_null(row,3,REAL)?{return Err("inactive IFC IEEE companions".into());}
        let value=match kind{"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"integer"=>IfcValue::Integer(row.integer(2)?),"real"=>IfcValue::Real(read_binary64(row,3,REAL)?),"string"=>IfcValue::String(reconstruct_text(control,row.text(4)?)?),"enum"=>IfcValue::Enum(reconstruct_text(control,row.text(5)?)?),"reference"=>{let word=word(row.text(6)?)?;if identities.get(&row.integer(7)?)!=Some(&word){return Err("IFC reference word differs from its related entity".into());}IfcValue::Reference(word)},"aggregate"|"typedValue"=>{let children=if kind=="aggregate"{aggregates.remove(&id)}else{typed.remove(&id)}.unwrap_or_default();let mut items=Vec::with_capacity(children.len());for child in children{items.push(complete.remove(&child.integer(3)?).ok_or("invalid IFC value ownership")?);tick(control,count)?;}if kind=="aggregate"{IfcValue::Aggregate(items)}else{IfcValue::TypedValue{name:reconstruct_text(control,row.text(8)?)?,items}}},_=>return Err("unknown IFC value kind".into())};complete.insert(id,value);
    }}}if visited.len()!=records.len()||!aggregates.is_empty()||!typed.is_empty(){return Err("unowned IFC value entity".into());}Ok(complete)
}
fn take(rows:Vec<&SqliteRow>,index:usize,values:&mut BTreeMap<i64,IfcValue>,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<IfcValue>,String>{let mut result=Vec::with_capacity(rows.len());for row in rows{result.push(values.remove(&row.integer(index)?).ok_or("missing IFC argument value")?);tick(control,count)?;}Ok(result)}
fn header(db:&SqliteDatabase,table:&str,values:&mut BTreeMap<i64,IfcValue>,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<IfcValue>,String>{let rows=ordered(db.table(table)?.rows.iter().collect(),2,control,count)?;for row in &rows{if row.integer(1)?!=1{return Err("IFC header argument belongs to another header".into());}tick(control,count)?;}take(rows,3,values,control,count)}
fn native_string(value:&str,control:&mut SqliteSnapshotControl<'_>,bytes:&mut usize)->Result<(),String>{*bytes=bytes.checked_add(value.len().checked_mul(16).and_then(|n|n.checked_add(64)).ok_or("IFC native string size overflow")?).ok_or("IFC native encoding size overflow")?;control.check_value_bytes(*bytes)?;if *bytes>control.limits().max_file_bytes{return Err("IFC native encoding exceeds file byte limit".into());}if value.len()>65536{control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;}Ok(())}
fn native_values(roots:&[IfcValue],control:&mut SqliteSnapshotControl<'_>,bytes:&mut usize,count:&mut usize)->Result<(),String>{control.check_rows(roots.len())?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,*count,0)?;let mut pending=Vec::with_capacity(roots.len());for(index,value)in roots.iter().enumerate(){pending.push(value);if index%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,*count,0)?;}}while let Some(value)=pending.pop(){*count=count.checked_add(1).ok_or("IFC native encoding count overflow")?;control.check_rows(*count)?;let overhead=match value{IfcValue::String(value)|IfcValue::Enum(value)=>{native_string(value,control,bytes)?;32},IfcValue::Real(value)=>{if !value.is_finite(){return Err("IFC4 native Part21 syntax cannot encode a non-finite real; owned SQLite preserves its IEEE word".into());}512},IfcValue::Aggregate(items)|IfcValue::TypedValue{items,..}=>{control.check_rows(pending.len().checked_add(items.len()).ok_or("IFC native pending count overflow")?)?;for(index,item)in items.iter().enumerate(){pending.push(item);if index%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,*count,0)?;}}if let IfcValue::TypedValue{name,..}=value{native_string(name,control,bytes)?;}32},_=>32};*bytes=bytes.checked_add(overhead).ok_or("IFC native encoding size overflow")?;control.check_value_bytes(*bytes)?;if *bytes>control.limits().max_file_bytes{return Err("IFC native encoding exceeds file byte limit".into());}if *count%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,*count,0)?;}}Ok(())}
impl ArtifactSqliteSnapshot for IfcSnapshot{
    fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;let mut bytes=1024usize;let mut count=0usize;control.check_value_bytes(bytes)?;for roots in [&self.header.file_description,&self.header.file_name,&self.header.file_schema]{native_values(roots,control,&mut bytes,&mut count)?;}for(index,entity)in self.entities.iter().enumerate(){native_string(&entity.name,control,&mut bytes)?;native_values(&entity.args,control,&mut bytes,&mut count)?;for part in &entity.complex{native_string(&part.name,control,&mut bytes)?;native_values(&part.args,control,&mut bytes,&mut count)?;}bytes=bytes.checked_add(128).ok_or("IFC native entity size overflow")?;control.check_value_bytes(bytes)?;if bytes>control.limits().max_file_bytes{return Err("IFC native encoding exceeds file byte limit".into());}if index%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index,self.entities.len())?;}}control.checkpoint(SqliteSnapshotPhase::EncodeNative,count,count)?;Ok(())}
    const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
    fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut predicted=3usize;for size in [self.entities.len(),self.header.file_description.len(),self.header.file_name.len(),self.header.file_schema.len()]{predicted=predicted.checked_add(size).ok_or("IFC projected count overflow")?;}control.check_rows(predicted)?;control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;let mut identities=BTreeMap::new();for(index,entity)in self.entities.iter().enumerate(){if identities.insert(entity.id,ordinal(index+1)?).is_some(){return Err("duplicate IFC instance identifier".into());}if index%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,index,self.entities.len())?;}}
        let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key("ifc_document",1,&[Cell::Text(&self.schema),Cell::Integer(1)])?;p.insert_key("ifc_header",1,&[])?;for(table,values)in [("ifc_file_description_argument",&self.header.file_description),("ifc_file_name_argument",&self.header.file_name),("ifc_file_schema_argument",&self.header.file_schema)]{for(index,value)in values.iter().enumerate(){project_value(value,Owner::Header(table,index),&identities,&mut p)?;}}
        for(index,entity)in self.entities.iter().enumerate(){let id=*identities.get(&entity.id).ok_or("missing IFC identity")?;let word=entity.id.to_string();p.insert_key("ifc_entity",id,&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Text(&word),Cell::Text(&entity.name)])?;p.check_rows(entity.args.len().checked_add(entity.complex.len()).ok_or("IFC member count overflow")?)?;for(index,value)in entity.args.iter().enumerate(){project_value(value,Owner::Argument(Some(id),None,index),&identities,&mut p)?;}for(index,part)in entity.complex.iter().enumerate(){let complex=p.insert("ifc_complex_type",&[Cell::Integer(id),Cell::Integer(ordinal(index)?),Cell::Text(&part.name)])?;p.check_rows(part.args.len())?;for(index,value)in part.args.iter().enumerate(){project_value(value,Owner::Argument(None,Some(complex),index),&identities,&mut p)?;}}}p.finish()
    }
    fn from_sqlite_database(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(db,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;control.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;let mut count=0;for(table,columns)in [("ifc_document",3),("ifc_header",1),("ifc_file_description_argument",4),("ifc_file_name_argument",4),("ifc_file_schema_argument",4),("ifc_entity",5),("ifc_complex_type",4),("ifc_argument",5),("ifc_value",11),("ifc_aggregate_element",4),("ifc_typed_argument",4)]{let mut ids=BTreeSet::new();for row in &db.table(table)?.rows{if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns||!ids.insert(row.rowid){return Err("invalid IFC relational identity or columns".into());}tick(control,&mut count)?;}}
        let root=db.table("ifc_document")?.single_row()?;if root.rowid!=1||root.integer(2)?!=1||db.table("ifc_header")?.single_row()?.rowid!=1{return Err("invalid IFC document/header ownership".into());}let rows=ordered(db.table("ifc_entity")?.rows.iter().collect(),2,control,&mut count)?;let mut identities=BTreeMap::new();let mut words=BTreeSet::new();for row in &rows{let word=word(row.text(3)?)?;if row.integer(1)?!=1||!words.insert(word){return Err("invalid IFC instance ownership or duplicate word".into());}identities.insert(row.rowid,word);tick(control,&mut count)?;}
        let mut complex=groups(db,"ifc_complex_type",1,2,control,&mut count)?;for owner in complex.keys(){if !identities.contains_key(owner){return Err("dangling IFC complex owner".into());}}let mut complex_ids=BTreeSet::new();for row in &db.table("ifc_complex_type")?.rows{complex_ids.insert(row.rowid);tick(control,&mut count)?;}let mut args=BTreeMap::<(bool,i64),Vec<&SqliteRow>>::new();for row in &db.table("ifc_argument")?.rows{let owner=match(&row.values[1],&row.values[2]){(SqliteValue::Integer(id),SqliteValue::Null)if identities.contains_key(id)=>(false,*id),(SqliteValue::Null,SqliteValue::Integer(id))if complex_ids.contains(id)=>(true,*id),_=>return Err("IFC argument must have one existing owner".into())};args.entry(owner).or_default().push(row);tick(control,&mut count)?;}for rows in args.values_mut(){*rows=ordered(std::mem::take(rows),3,control,&mut count)?;}
        let mut values=values(db,&identities,control,&mut count)?;let header=IfcHeader{file_description:header(db,"ifc_file_description_argument",&mut values,control,&mut count)?,file_name:header(db,"ifc_file_name_argument",&mut values,control,&mut count)?,file_schema:header(db,"ifc_file_schema_argument",&mut values,control,&mut count)?};let mut entities=Vec::with_capacity(rows.len());for row in rows{let primary=take(args.remove(&(false,row.rowid)).unwrap_or_default(),4,&mut values,control,&mut count)?;let mut parts=Vec::new();for part in complex.remove(&row.rowid).unwrap_or_default(){parts.push(IfcComplexType{name:reconstruct_text(control,part.text(3)?)?,args:take(args.remove(&(true,part.rowid)).unwrap_or_default(),4,&mut values,control,&mut count)?});tick(control,&mut count)?;}entities.push(IfcEntity{id:*identities.get(&row.rowid).ok_or("missing IFC native identity")?,name:reconstruct_text(control,row.text(4)?)?,args:primary,complex:parts});tick(control,&mut count)?;}if !values.is_empty()||!args.is_empty()||!complex.is_empty(){return Err("unowned IFC relationship".into());}let result=Self{schema:reconstruct_text(control,root.text(1)?)?,header,entities};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,count)?;Ok(result)
    }
    fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_os_kernel::io_schema::ArtifactDialect,db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.ifc"||dialect.standard!="4"||dialect.subset!="*"{return Err(String::from("unknown owned IFC4 snapshot dialect").into());}let root=db.table("ifc_document")?.single_row()?;if root.rowid!=1||root.text(1)?!=self.schema{return Err(String::from("IFC4 document identity differs from its projection").into());}Ok(semio_framework_os_kernel::io_schema::IoOutcome{value:(),diagnostics:Vec::new()})}
}
